export async function runSyntheticProbe(fetcher,{url,expectStatus=200,requiredFields=[],timeoutMs=5000}={}){const started=Date.now();let timer;try{const timeout=new Promise((_,rej)=>timer=setTimeout(()=>rej(new Error('PROBE_TIMEOUT')),timeoutMs));const res=await Promise.race([fetcher(url),timeout]);const body=typeof res.json==='function'?await res.json():res.body;const missing=requiredFields.filter(k=>body?.[k]===undefined);return {ok:Number(res.status??expectStatus)===expectStatus&&!missing.length,status:Number(res.status??expectStatus),missing,latencyMs:Date.now()-started}}catch(e){return {ok:false,error:String(e.message||e),latencyMs:Date.now()-started}}finally{clearTimeout(timer)}}
